# FUNCTIONS
def Populations():
    Pop = np.zeros((par.nData, par.Nt), dtype = np.float64)
    ρt  = np.zeros((par.nData, par.Nt * par.Nt), dtype = np.complex128)
    for j in range(len(par.μMat_sp)):
        print('Mu parameter: ', par.μMat_sp[j], par.μMat_id[j])
        ρt[:,:] = 0.0
        for i in range(par.Cpus):
            ρt += np.loadtxt(f'./Data/rhoRe_{i}_{par.μMat_id[j,0]}_{par.μMat_id[j,1]}.txt', dtype = np.complex128)
        ρt /= (len(par.μMat_sp) * par.Cpus)
        for k in range(par.nData):
            Pop[k,:] += np.real(np.diag(ρt[k,:].reshape((par.Nt, par.Nt))))
    return Pop

def LoadData():
    R1t = np.zeros((par.nData), dtype = np.complex128)
    ρt  = np.zeros((par.nData, par.Nt * par.Nt), dtype = np.complex128)
    for j in range(len(par.μMat_sp)):
        print('Mu parameter: ', par.μMat_sp[j], par.μMat_id[j])
        ρt[:,:] = 0.0
        for i in range(par.Cpus):
            ρt += np.loadtxt(f'./Data/rhoRe_{i}_{par.μMat_id[j,0]}_{par.μMat_id[j,1]}.txt', dtype = np.complex128)
        ρt /= (len(par.μMat_sp) * par.Cpus)
        for k in range(par.nData):
            ρNt = ρt[k,:].reshape((par.Nt, par.Nt)) * par.μMat_sp[j]
            R1t[k] += 1j * np.trace(ρNt @ μ0)
    return R1t
    
def Fourier1D():
    c_cm_per_fs = sc.c * 100.0 / 1e15 
    Δω   = 750
    ωmin = (par.E0/par.cm2au - Δω) * 2 * np.pi * c_cm_per_fs  
    ωmax = (par.E0/par.cm2au + Δω) * 2 * np.pi * c_cm_per_fs  
    lenω = 1001
    ω    = np.linspace(ωmin, ωmax, lenω)
    δω   = ω[1] - ω[0]

    τ    = time 
    T    = τ.max()
    δtN  = τ[1] - τ[0]

    window = np.cos(np.pi * τ / (2 * T))
    phase  = np.exp(1j * ω[:, None] * τ[None, :])
    R1ω    = np.sum((R1t * window)[None, :] * phase, axis=1) * δtN
    R1ω_Area = np.trapz(np.real(R1ω), dx = δω)

    τ    = np.array(x_curve3) 
    T    = τ.max()
    δtN  = τ[1] - τ[0]

    window = np.cos(np.pi * τ / (2 * T))
    phase  = np.exp(1j * ω[:, None] * τ[None, :])
    R1ωE    = np.sum((np.array(y_curve3) * window)[None, :] * phase, axis=1) * δtN
    R1ωE_Area = np.trapz(R1ωE, dx = δω)

    return R1ω, R1ωE, ω / ((2 * np.pi) * c_cm_per_fs)
    
# ===================================
time = par.Sim_time[::par.nskip]/par.fs2au 

if par.Spectra:
    μ0   = (par.μMat @ par.ρ0) - (par.ρ0 @ par.μMat)
    R1t = LoadData()
    R1ω, R1ωE, ω = Fourier1D()

    fig, ax = plt.subplots(2,1, figsize = (3,3), sharex=True)
    ax[0].plot(time, np.real(R1t)/np.max(np.abs(R1t)), lw = 2, c = col[0], label = 'Real')
    ax[0].plot(x_curve3, y_curve3, lw = 1, c = 'k', ls = '--')
    ax[1].plot(time, np.imag(R1t)/np.max(np.abs(R1t)), lw = 2, c = col[1], label = 'Imaginary')
    ax[0].set_ylabel('R1(t)')
    ax[1].set_xlabel('Time (fs)')
    ax[1].set_ylabel('R1(t)')
    ax[0].set_xlim(0,time[-1])
    ax[0].legend(frameon=False, fontsize = 5)
    ax[1].legend(frameon=False, fontsize = 5)
    plt.savefig('./Images/R1t.png', dpi = 300, bbox_inches = 'tight')
    plt.close()

    fig, ax = plt.subplots(figsize = (3,3))
    ax.axvline(par.E0/par.cm2au, lw = 1, c = 'k', ls = '--')
    ax.plot(ω - par.E0/par.cm2au, np.imag(R1ω)/np.max(np.abs(R1ω)), lw = 3, c = col[0], label = 'Real')
    ax.plot(ω - par.E0/par.cm2au, np.imag(R1ωE)/np.max(np.abs(R1ωE)), lw = 1, c = 'k', ls = '--')
    ax.set_xlabel('Frequency (cm$^{-1}$)')
    ax.set_ylabel('R1(ω)')
    ax.set_xlim(ω[0] - par.E0/par.cm2au,ω[-1] - par.E0/par.cm2au)
    # ax.set_ylim(0,11)
    ax.legend(frameon=False, fontsize = 5)
    plt.savefig('./Images/R1ω.png', dpi = 300, bbox_inches = 'tight')
    plt.close()

else:
    Pop = Populations()

    fig, ax = plt.subplots(figsize = (5,3))
    ax.plot(time, Pop[:,0], lw = 2, c = col[0], label = '|0>')
    ax.plot(time, Pop[:,1], lw = 2, c = col[1], label = '|1>')
    ax.plot(time, Pop[:,2], lw = 2, c = col[2], label = '|2>')
    ax.plot(x_curve1[:-10], y_curve1[:-10], lw = 0.5, ls = '--',c = 'black')
    ax.plot(x_curve2[:-12], y_curve2[:-12], lw = 0.5, ls = '--',c = 'black')
    ax.set_xlabel('Time (fs)')
    ax.set_ylabel('Population')
    ax.set_xlim(0,time[-1])
    ax.legend(frameon=False, fontsize = 5)
    plt.savefig('./Images/Populations.png', dpi = 300, bbox_inches = 'tight')
    plt.close()

